// Generate a uniform random number in [0, 1) using a simple linear congruential generator (LCG)
auto uniform01 = [&](unsigned int &s) -> double {
    // LCG parameters (same as used in randomgen.cpp)
    const unsigned int a = 1664525u;
    const unsigned int c = 1013904223u;
    const unsigned int m = 0xFFFFFFFFu; // 2^32 - 1
    s = (a * s + c) & m;
    return static_cast<double>(s) / static_cast<double>(m + 1u);
};

int hits = 0;
double range = b - a;
for (int i = 0; i < n_points; ++i) {
    // Sample x uniformly in [a, b]
    double x = a + uniform01(seed) * range;
    // Sample y uniformly in [0, fmax]
    double y = uniform01(seed) * fmax;
    // Count a hit if y <= f(x)
    if (y <= f(x)) {
        ++hits;
    }
}

// The estimated integral is the fraction of hits times the area of the sampling rectangle
return static_cast<double>(hits) / static_cast<double>(n_points) * range * fmax;
